import { MakeLogicType, actions, afterMount, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import { router } from 'kea-router'

import { teamLogic } from 'scenes/teamLogic'
import { urls } from 'scenes/urls'

import { canvasesForkCreate } from 'products/canvas/frontend/generated/api'
import type { CanvasApi } from 'products/canvas/frontend/generated/api.schemas'

export interface CodeCanvasForkLogicProps {
    shareToken: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface codeCanvasForkLogicValues {
    currentTeamId: number | null // teamLogic
    copy: CanvasApi | null
    copyLoading: boolean
    error: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface codeCanvasForkLogicActions {
    forkCanvas: () => {
        value: true
    }
    forkCanvasFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    forkCanvasSuccess: (
        copy: CanvasApi,
        payload?: {
            value: true
        }
    ) => {
        copy: CanvasApi
        payload?: {
            value: true
        }
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface codeCanvasForkLogicMeta {
    key: string
}

export type codeCanvasForkLogicType = MakeLogicType<
    codeCanvasForkLogicValues,
    codeCanvasForkLogicActions,
    CodeCanvasForkLogicProps,
    codeCanvasForkLogicMeta
>

/**
 * Copies a publicly shared canvas into the signed-in user's own project, then hands off to the
 * desktop bridge for the copy. The share token comes from the public page's "open a copy" button.
 */
export const codeCanvasForkLogic = kea<codeCanvasForkLogicType>([
    path(['scenes', 'code-canvas', 'codeCanvasForkLogic']),
    props({} as CodeCanvasForkLogicProps),
    key((props) => props.shareToken),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    actions({
        forkCanvas: true,
    }),
    loaders(({ props, values }) => ({
        copy: {
            __default: null as CanvasApi | null,
            forkCanvas: async () => {
                if (!values.currentTeamId) {
                    throw new Error('No project selected')
                }
                return await canvasesForkCreate(String(values.currentTeamId), { share_token: props.shareToken })
            },
        },
    })),
    reducers({
        error: [
            null as string | null,
            {
                forkCanvas: () => null,
                forkCanvasFailure: (_, { error }) => error,
            },
        ],
    }),
    listeners({
        forkCanvasSuccess: ({ copy }) => {
            if (copy) {
                router.actions.replace(urls.codeCanvasLink(copy.channel, copy.id))
            }
        },
    }),
    afterMount(({ actions }) => {
        actions.forkCanvas()
    }),
])
